DELETE FROM COWAY_DOCTOR_AS
 WHERE 1 = 1
   AND IF_FLAG != 'Y'
   AND MBLNR = #{MBLNR}
   AND DELDA = #{DELDA}
   AND PERNR = #{PERNR}
   AND REPAIR_CODE = #{REPAIR_CODE}

