/* master.mpif.sendMasterMpIfCowayDoctorAsList */
UPDATE COWAY_DOCTOR_AS
   SET IF_FLAG = 'N'
 WHERE 1 = 1
   AND MBLNR = #{MBLNR}
   AND PERNR = #{PERNR}
   AND DELDA = #{DELDA}
   AND REPAIR_CODE = #{REPAIR_CODE}
   AND IF_FLAG = 'T'

/* master.mpif.saveMasterMpIfCowayDoctorAsList */
UPDATE COWAY_DOCTOR_AS
   SET BIGO  = #{BIGO}
     , IF_FLAG = 'T'
 WHERE 1 = 1
   AND MBLNR = #{MBLNR}
   AND PERNR = #{PERNR}
   AND DELDA = #{DELDA}
   AND REPAIR_CODE = #{REPAIR_CODE}
   AND IF_FLAG IN ('T', 'E')
